<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserIdentity\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Access\UserIdentity\Infrastructure\Driver\Rest\UserIdentityAllowController;
use Civi\Lughauth\Features\Access\UserIdentity\Infrastructure\Driver\Rest\UserIdentityListController;
use Civi\Lughauth\Features\Access\UserIdentity\Infrastructure\Driver\Rest\UserIdentityCreateController;
use Civi\Lughauth\Features\Access\UserIdentity\Infrastructure\Driver\Rest\UserIdentityRetrieveController;
use Civi\Lughauth\Features\Access\UserIdentity\Infrastructure\Driver\Rest\UserIdentityUpdateController;
use Civi\Lughauth\Features\Access\UserIdentity\Infrastructure\Driver\Rest\UserIdentityDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Service\Visibility\UserIdentityRestrictFilterToVisibility;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Usecase\Create\UserIdentityCreateAllowDecision;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Usecase\Update\UserIdentityUpdateAllowDecision;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Usecase\Retrieve\UserIdentityRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Usecase\List\UserIdentityListAllowDecision;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Access\UserIdentity\Application\Usecase\Delete\UserIdentityDeleteAllowDecision;
use Civi\Lughauth\Features\Access\UserIdentity\Infrastructure\Driven\UserIdentityReadRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserIdentity\Infrastructure\Driven\UserIdentityWriteRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserIdentity\Domain\Gateway\UserIdentityReadGateway;
use Civi\Lughauth\Features\Access\UserIdentity\Domain\Gateway\UserIdentityWriteGateway;

class UserIdentityPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[UserIdentityReadGateway::class] = \DI\autowire(UserIdentityReadRepositoryAdapter::class);
        $def[UserIdentityWriteGateway::class] = \DI\autowire(UserIdentityWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/access/identity', [$this, 'setRoutesForUserIdentity']);
        $collector->group('/api/me/acl/access/identity', [$this, 'setRoutesForUserIdentityAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $bus): void
    {
        $bus->registerListener(UserIdentityRestrictFilterToVisibility::class, TenantAccesible::class);
        $bus->registerListener(UserIdentityCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $bus->registerListener(UserIdentityUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $bus->registerListener(UserIdentityRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $bus->registerListener(UserIdentityListAllowDecision::class, IsAuthenticatedListAllow::class);
        $bus->registerListener(UserIdentityDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("user-identity", "list", "READ");
            $handler->registerResourceAction("user-identity", "create", "WRITE");
            $handler->registerResourceAction("user-identity", "retrieve", "READ");
            $handler->registerResourceAction("user-identity", "update", "WRITE");
            $handler->registerResourceAction("user-identity", "delete", "WRITE");

            $handler->registerResourceAttribute("user-identity", "user", "MANAGE");
            $handler->registerResourceAttribute("user-identity", "relyingParty", "MANAGE");
            $handler->registerResourceAttribute("user-identity", "trustedClient", "MANAGE");
            $handler->registerResourceAttribute("user-identity", "roles", "MANAGE");
            $handler->registerResourceAttribute("user-identity", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForUserIdentityAcl(RouteCollectorProxy $userIdentityGroup): void
    {
        $userIdentityGroup->get('', [UserIdentityAllowController::class, 'genericAllow']);
        $userIdentityGroup->get('/{uid}', [UserIdentityAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForUserIdentity(RouteCollectorProxy $userIdentityGroup): void
    {
        $userIdentityGroup->get('', [UserIdentityListController::class, 'list']);
        $userIdentityGroup->post('', [UserIdentityCreateController::class, 'create']);
        $userIdentityGroup->get('/{uid}', [UserIdentityRetrieveController::class, 'retrieve']);
        $userIdentityGroup->put('/{uid}', [UserIdentityUpdateController::class, 'update']);
        $userIdentityGroup->delete('/{uid}', [UserIdentityDeleteController::class, 'delete']);
        $userIdentityGroup->delete('', [UserIdentityDeleteController::class, 'deleteAllForQuery']);
        $userIdentityGroup->get('/~/delete-status/{uid}', [UserIdentityDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
